class Solution {
    public int candy(int[] ratings) {
        int total = 0;
        for (int index = 0; index < ratings.length; index++) {
            int risingFromLeft = 0;
            for (int cursor = index; cursor > 0 && ratings[cursor] > ratings[cursor - 1]; cursor--) {
                risingFromLeft++;
            }
            int risingFromRight = 0;
            for (int cursor = index; cursor + 1 < ratings.length && ratings[cursor] > ratings[cursor + 1]; cursor++) {
                risingFromRight++;
            }
            total += Math.max(risingFromLeft, risingFromRight) + 1;
        }
        return total;
    }
}

